{
  "findings": [
    {
      "check_id": "CKV_K8S_16",
      "title": "Ingress TLS secret not properly configured",
      "resource": "kubernetes_ingress.pass",
      "severity": "HIGH",
      "explanation": "The ingress resource specifies a TLS secret, but there is no validation or enforcement of HTTPS-only traffic. This could allow unencrypted HTTP traffic, exposing sensitive data in transit."
    }
  ],
  "patched_code": "resource "kubernetes_ingress" "pass" {
  metadata {
    name = "example-ingress"
    namespace = "brian"
    annotations = {
      "nginx.ingress.kubernetes.io/force-ssl-redirect" = "true"
    }
  }

  spec {
    backend {
      service_name = "MyApp1"
      service_port = 8080
    }

    rule {
      http {
        path {
          backend {
            service_name = "MyApp1"
            service_port = 8080
          }

          path = "/app1/*"
        }

        path {
          backend {
            service_name = "MyApp2"
            service_port = 8080
          }

          path = "/app2/*"
        }
      }
    }

    tls {
      secret_name = "tls-secret"
    }
  }
}
",
  "fix_summary": "Added an annotation to enforce HTTPS-only traffic by redirecting HTTP to HTTPS."
}
